BEGIN;
DO $test$
DECLARE t uuid:=gen_random_uuid();t2 uuid:=gen_random_uuid();u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();u3 uuid:=gen_random_uuid();site uuid:=gen_random_uuid();qid uuid:=gen_random_uuid();w uuid:=gen_random_uuid();w2 uuid:=gen_random_uuid();tok uuid;tok2 uuid;v text;v2 text;res jsonb;items jsonb:='[{"name":"Prestation recette","quantity":3,"unit_price":1000,"discount":100}]';
BEGIN
 INSERT INTO public.tenants(id,name,enabled_modules) VALUES(t,'RECETTE DEVIS VERROU','["accounting"]'),(t2,'RECETTE AUTRE','[]');
 INSERT INTO auth.users(id,email,aud,role) SELECT id,id::text||'@example.invalid','authenticated','authenticated' FROM unnest(ARRAY[u,u2,u3]) id;
 INSERT INTO public.profiles(id,tenant_id,role,site_access_mode,full_name,is_active) VALUES(u,t,'admin','all','Commercial A',true),(u2,t,'admin','all','Commercial B',true),(u3,t2,'admin','all','Autre entreprise',true) ON CONFLICT(id) DO UPDATE SET tenant_id=excluded.tenant_id,role=excluded.role,site_access_mode=excluded.site_access_mode,full_name=excluded.full_name,is_active=true;
 INSERT INTO public.sites(id,tenant_id,name,is_active) VALUES(site,t,'Magasin recette',true);
 INSERT INTO public.quotes(id,tenant_id,site_id,user_id,quote_number,subtotal,total,status,doc_header) VALUES(qid,t,site,u,'DEV-RECETTE-'||qid::text,2000,2000,'draft','{"ancienne_cle":"conservée"}');
 INSERT INTO public.quote_items(tenant_id,quote_id,name,quantity,unit_price,total) VALUES(t,qid,'Prestation recette',2,1000,2000);
 PERFORM set_config('request.jwt.claim.sub',u::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 res:=public.document_edit_lease(t,'quote',qid::text,w,'acquire');tok:=(res->>'token')::uuid;
 IF res->>'state' IS DISTINCT FROM 'held' THEN RAISE EXCEPTION 'Verrou initial absent';END IF;
 res:=public.load_locked_quote_edit(t,qid,w,tok);v:=res->>'version';
 IF v IS NULL THEN RAISE EXCEPTION 'Version initiale absente';END IF;
 PERFORM set_config('request.jwt.claim.sub',u2::text,true);
 res:=public.document_edit_lease(t,'quote',qid::text,w2,'acquire');
 IF res->>'state' IS DISTINCT FROM 'busy' THEN RAISE EXCEPTION 'Double verrou';END IF;
 BEGIN PERFORM public.save_locked_quote_edit(t,qid,w2,tok,v,items,NULL,NULL,'','{}',NULL,true);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Jeton volé accepté';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 BEGIN PERFORM public.change_locked_quote_status(t,qid,v,'accepted');RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Changement de statut malgré le verrou';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 res:=public.document_edit_lease(t,'quote',qid::text,w2,'request');
 PERFORM set_config('request.jwt.claim.sub',u3::text,true);
 BEGIN PERFORM public.read_quote_action_snapshot(t,qid);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Accès inter-entreprises';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 BEGIN PERFORM public.save_locked_quote_edit(t,qid,w,tok,v,jsonb_set(items,'{0,quantity}','0'),NULL,NULL,'','{}',NULL,true);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Quantité nulle acceptée';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 res:=public.document_edit_lease(t,'quote',qid::text,w,'status');
 IF res->>'state' IS DISTINCT FROM 'held' OR res->>'request_state' IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'Échec a libéré le verrou';END IF;
 res:=public.save_locked_quote_edit(t,qid,w,tok,v,items,NULL,NULL,'Recette','{"reference":"test"}',NULL,true);
 IF res->>'success' IS DISTINCT FROM 'true' OR res->>'lock_released' IS DISTINCT FROM 'true' OR (res->'quote'->>'total')::numeric<>2900 THEN RAISE EXCEPTION 'Enregistrement incorrect';END IF;
 PERFORM set_config('request.jwt.claim.sub',u2::text,true);
 res:=public.document_edit_lease(t,'quote',qid::text,w2,'status');tok2:=(res->>'token')::uuid;
 IF res->>'state' IS DISTINCT FROM 'held' OR tok2=tok THEN RAISE EXCEPTION 'Transfert incorrect';END IF;
 BEGIN PERFORM public.save_locked_quote_edit(t,qid,w2,tok2,v,items,NULL,NULL,'','{}',NULL);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Version périmée acceptée';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.change_locked_quote_status(t,qid,v,'accepted',w2,tok2);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Ancienne version acceptée pour statut';EXCEPTION WHEN serialization_failure THEN NULL;END;
 res:=public.load_locked_quote_edit(t,qid,w2,tok2);v2:=res->>'version';
 BEGIN PERFORM public.change_locked_quote_status(t,qid,v2,'converted',w2,tok2);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Conversion fictive acceptée';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 res:=public.change_locked_quote_status(t,qid,v2,'accepted',w2,tok2);
 IF res->'quote'->>'status' IS DISTINCT FROM 'accepted' THEN RAISE EXCEPTION 'Statut incorrect';END IF;
 v2:=res->>'version';
 res:=public.document_edit_lease(t,'quote',qid::text,w2,'acquire');tok2:=(res->>'token')::uuid;
 BEGIN PERFORM public.save_locked_quote_edit(t,qid,w2,tok2,v2,items,NULL,NULL,'','{}',NULL);RAISE EXCEPTION USING ERRCODE='P9098',MESSAGE='Devis accepté modifié';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 PERFORM public.document_edit_lease(t,'quote',qid::text,w2,'release',tok2);
 res:=public.change_locked_quote_status(t,qid,v2,'rejected');
 IF res->'quote'->>'status' IS DISTINCT FROM 'rejected' THEN RAISE EXCEPTION 'Refus incorrect';END IF;
 EXECUTE 'RESET ROLE';
 IF (SELECT total FROM public.quotes WHERE id=qid)<>2900 OR (SELECT count(*) FROM public.quote_items WHERE quote_id=qid)<>1 OR (SELECT total FROM public.quote_items WHERE quote_id=qid)<>2900 THEN RAISE EXCEPTION 'Totaux incohérents';END IF;
 IF (SELECT doc_header->>'ancienne_cle' FROM public.quotes WHERE id=qid) IS DISTINCT FROM 'conservée' THEN RAISE EXCEPTION 'En-tête historique perdu';END IF;
 IF (SELECT count(*) FROM public.audit_logs WHERE reference_id=qid AND action IN ('quote_edit','quote_status'))<>3 THEN RAISE EXCEPTION 'Audit incomplet';END IF;
 IF EXISTS(SELECT 1 FROM public.document_edit_leases WHERE tenant_id=t) THEN RAISE EXCEPTION 'Verrou résiduel';END IF;
 IF has_function_privilege('anon','public.save_locked_quote_edit(uuid,uuid,uuid,uuid,text,jsonb,uuid,date,text,jsonb,uuid,boolean)','EXECUTE') OR has_function_privilege('authenticated','public._quote_edit_snapshot(uuid,uuid)','EXECUTE') OR has_function_privilege('anon','public.change_locked_quote_status(uuid,uuid,text,text,uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'API exposée sans contrôle';END IF;
END $test$;
ROLLBACK;
